(23, 231, NULL, 29, 'itsjkiprotich@gmail.com', '<?xml version=\"1.0\" encoding=\"ISO-8859-1\"?>\r\n<!DOCTYPE ichicsr SYSTEM \"https://eudravigilance.ema.europa.eu/dtd/icsr21xml.dtd\">\r\n<ichicsr lang=\"en\">\r\n    <ichicsrmessageheader>\r\n        <messagetype>ichicsr</messagetype>\r\n        <messageformatversion>2.1</messageformatversion>\r\n        <messageformatrelease>2.0</messageformatrelease>\r\n        <messagenumb>70081570_PRD</messagenumb>\r\n        <messagesenderidentifier>VIIV</messagesenderidentifier>\r\n        <messagereceiveridentifier>PPB</messagereceiveridentifier>\r\n        <messagedateformat>204</messagedateformat>\r\n        <messagedate>20250717102622</messagedate>\r\n    </ichicsrmessageheader>\r\n    <safetyreport>\r\n        <safetyreportversion>2</safetyreportversion>\r\n        <safetyreportid>US-VIIV HEALTHCARE-US2025046717</safetyreportid>\r\n        <primarysourcecountry>US</primarysourcecountry>\r\n        <occurcountry>US</occurcountry>\r\n        <transmissiondateformat>102</transmissiondateformat>\r\n        <transmissiondate>20250717</transmissiondate>\r\n        <reporttype>2</reporttype>\r\n        <serious>1</serious>\r\n        <seriousnessdeath>2</seriousnessdeath>\r\n        <seriousnesslifethreatening>1</seriousnesslifethreatening>\r\n        <seriousnesshospitalization>1</seriousnesshospitalization>\r\n        <seriousnessdisabling>2</seriousnessdisabling>\r\n        <seriousnesscongenitalanomali>2</seriousnesscongenitalanomali>\r\n        <seriousnessother>2</seriousnessother>\r\n        <receivedateformat>102</receivedateformat>\r\n        <receivedate>20250416</receivedate>\r\n        <receiptdateformat>102</receiptdateformat>\r\n        <receiptdate>20250712</receiptdate>\r\n        <additionaldocument>1</additionaldocument>\r\n        <documentlist>Auto accepted by rule\r\nprocessed by AAK on 21-APR-2025,processed by AAK on 21-APR-2025,Auto accepted</documentlist>\r\n        <fulfillexpeditecriteria>1</fulfillexped