INSERT INTO `notifications` (`id`, `user_id`, `type`, `model`, `foreign_key`, `title`, `url`, `system_message`, `user_message`, `deleted`, `deleted_date`, `created`, `modified`) VALUES
(743, 2, 'screening_feedback', 'ApplicationStage', 82, 'Protocol screening feedback', NULL, '<p>\r\n	Dear manager,</p>\r\n<p>\r\n	<u><strong>Screening Feedback</strong></u></p>\r\n<p>\r\n	<strong>Subject</strong>: </p>\r\n<p>\r\n	<strong>Content</strong></p>\r\n<p>\r\n	<h3 style=\"text-align: center;\">\r\n	<img alt=\"\" src=\"data:image/png;base64,\" /></h3>\r\n<p style=\"text-align: center;\">\r\n	<strong>MINISTRY</strong> <strong>OF</strong> <strong>H</strong><strong>EALTH</strong></p>\r\n<p style=\"text-align: center;\">\r\n	<strong>PHARMACY</strong> <strong>AND</strong> <strong>POISONS</strong> <strong>BOARD</strong></p>\r\n<address>\r\n	<span style=\"font-size:11px;\">Telegrams: &quot;MINIHEALTH&quot;, Nairobi <span style=\"float:right;\"> PHARMACY AND POISONS BOARD HOUSE </span></span></address>\r\n<address>\r\n	<span style=\"font-size:11px;\">Telephone: Nairobi 020 2716905/6 , 3562107 <span style=\"float:right;\"> LENANA ROAD &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; </span></span></address>\r\n<address>\r\n	<span style=\"font-size:11px;\">Cellphone: 0733 &ndash; 884411/0720608811 <span style=\"float:right;\"> P.O. BOX 27663-00506 &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; </span></span></address>\r\n<address>\r\n	<span style=\"font-size:11px;\">Fax: 2713409&nbsp;<span style=\"float:right;\"> NAIROBI&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></address>\r\n<p>\r\n	Enter Comment Here</p>\r\n<h4 class=\"text-success\" style=\"margin: 10px 0px; font-family: Tahoma, Arial, sans-serif; line-height: 20px; color: rgb(70, 136, 71); text-rendering: optimizelegibility; font-size: 17.5px;\">\r\n	ECCT/24/02/01</h4>\r\n<p>\r\n	&nbsp;</p>\r\n<p>\r\n	Kindly address the followinf screening queries,&#39;&#39;</p>\r\n<p>\r\n	&nbsp;</p>\r\n<p>\r\n	&nbsp;</p>\r\n<p style=\"margin-left:67.5pt;\">\r\n	1.1.1&nbsp;&nbsp; The Receiving officer shall ensure that the application is complete as per the checklist above</p>\r\n<p style=\"margin-left:67.5pt;\">\r\n	1.1.2&nbsp;&nbsp; All applications for annual approval must also be submitted through the clinical trials registry at <a href=\"http://www.ctr.pharmacyboardkenya.org\">www.ctr.pharmacyboardkenya.org</a></p>\r\n<p style=\"margin-left:67.5pt;\">\r\n	1.1.3&nbsp;&nbsp; The head of clinical trials or delegated person shall review the application.</p>\r\n<p style=\"margin-left:67.5pt;\">\r\n	1.1.4&nbsp;&nbsp; In cases that require specialized evaluation, head clinical trials shall provide access rights on the online registry to the initial reviewers of the protocol</p>\r\n<p style=\"margin-left:67.5pt;\">\r\n	1.1.5&nbsp;&nbsp; Head Clinical Trials shall communicate to the applicant; issue an annual renewal approval if satisfactory or rejection letter to the applicant</p>\r\n<p style=\"margin-left:67.5pt;\">\r\n	&nbsp;</p>\r\n<p style=\"margin-left:67.5pt;\">\r\n	&nbsp;</p>\r\n<p style=\"margin-left:67.5pt;\">\r\n	&nbsp;</p>\r\n<p style=\"margin-left:67.5pt;\">\r\n	Signed</p>\r\n<p style=\"margin-left:67.5pt;\">\r\n	<img alt=\"\" src=\"data:image/png;base64,\" /></p>\r\n<p style=\"margin-left:67.5pt;\">\r\n	SKK</p>\r\n<p>\r\n	&nbsp;</p>\r\n</p>\r\n<p>\r\n	Link:</p>\r\n<p>\r\n	<a href=\"http://45.79.161.190:8080/manager/applications/view/11\">ECCT/24/02/01</a></p>\r\n<p>\r\n	Regards,</p>\r\n<p>\r\n	PPB</p>\r\n', NULL, 0, NULL, '2024-02-09 10:12:33', '2024-02-09 10:12:33');
